    "model-adapter/README.md": "# __PACKAGE_NAME__\n\nAGH model-adapter starter. Requires Node.js 24.10 or later and matching AGH package builds.\n\n__SETUP_GUIDE__\n\nmain registers a structural adapter through modelAdapters. Configure provider.adapters with the registration id, a route whose api equals adapter.api, a model on that route, and keyless: true for this no-network demo. Real adapters must implement their protocol and credential requirements. Instances own dispose; registration-wide resources belong in cleanup. Successful reload publishes the adapter for new sessions; existing sessions keep their generation. Process backends still require a restart. The fixed development reply is not a real model integration.\n",
    "model-adapter/package.json": "{\n  \"name\": \"__PACKAGE_NAME__\",\n  \"version\": \"0.1.0\",\n  \"type\": \"module\",\n  \"license\": \"Apache-2.0\",\n  \"engines\": {\n    \"node\": \">=24.10\"\n  },\n  \"exports\": \"./dist/index.js\",\n  \"files\": [\n    \"dist\",\n    \"client\",\n    \"skills\",\n    \"mcp.json\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"test\": \"node --import tsx --test test/*.test.mjs\"\n  },\n  \"dependencies\": {\n    \"@agnes/plugin-runtime\": \"0.0.0\",\n    \"@agnes/extension-api\": \"1.4.0\",\n    \"@agnes/protocol\": \"0.0.0\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"7.0.2\",\n    \"@types/node\": \"26.4.1\",\n    \"tsx\": \"4.23.13\"\n  },\n  \"agnes\": {\n    \"plugins\": [\n      {\n        \"export\": \"main\",\n        \"apiRange\": \"^1.4.0\",\n        \"id\": \"ext:__PACKAGE_NAME__/main\",\n        \"inject\": [\n          \"modelAdapters\"\n        ]\n      }\n    ],\n    \"hostProvidedExternals\": {\n      \"@agnes/plugin-runtime\": \"0.0.0\",\n      \"@agnes/extension-api\": \"1.4.0\",\n      \"@agnes/protocol\": \"0.0.0\"\n    },\n    \"kinds\": [\n      \"model-adapter\"\n    ],\n    \"capabilities\": {}\n  }\n}\n",
    "model-adapter/src/index.ts": "import type { ModelAdapterConfig, ModelAdapterInstance } from '@agnes/extension-api'\nimport {\n  type ModelAdapterPluginContext as Context,\n  defineAgnesPlugin,\n  defineModelAdapter,\n} from '@agnes/plugin-runtime'\n\n// Route.api selects this registration. Use your own wire-protocol identifier.\nexport const adapter = defineModelAdapter({\n  id: '__PACKAGE_NAME__',\n  version: '0.1.0',\n  api: '__SKILL_NAME__-wire',\n  capabilities: { imageInput: false, tools: false, streaming: true },\n  create(config: ModelAdapterConfig): ModelAdapterInstance {\n    const lifetime = new AbortController()\n    return {\n      id: '__PACKAGE_NAME__',\n      routes: () => [...config.routes],\n      models: (route) => config.routes.find((candidate) => candidate.route === route)?.models ?? [],\n      async *stream(_route, _request, options) {\n        const signal = AbortSignal.any([options.signal, lifetime.signal])\n        signal.throwIfAborted()\n        // Replace this deterministic reply with your wire protocol; pass signal to all I/O.\n        yield { type: 'text_delta', delta: 'Hello from __PACKAGE_NAME__' }\n        yield { type: 'done', reason: 'stop' }\n      },\n      dispose() {\n        lifetime.abort()\n      },\n    }\n  },\n})\n\nexport const main = defineAgnesPlugin({\n  inject: ['modelAdapters'],\n  apply(ctx: Context) {\n    ctx.modelAdapters.register(adapter)\n  },\n})\n",
    "model-adapter/test/adapter.test.mjs": "import assert from 'node:assert/strict'\nimport { test } from 'node:test'\nimport { runModelAdapter } from '@agnes/plugin-runtime/testkit'\nimport { adapter } from '../dist/index.js'\n\ntest('catalog and deterministic stream, including cancellation', async () => {\n  const model = {\n    id: 'demo-model',\n    name: 'Demo',\n    route: 'demo',\n    api: adapter.api,\n    baseUrl: 'https://demo.invalid',\n    reasoning: false,\n    input: ['text'],\n    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },\n    contextWindow: 128000,\n    maxTokens: 8192,\n    toolCallFormats: ['native'],\n    thinkingReplay: 'native',\n    contract_id: null,\n  }\n  const request = {\n    kind: 'inference',\n    sessionKey: 'adapter-test',\n    slot: 'primary',\n    route: 'demo',\n    model: model.id,\n    contractId: null,\n    derivedHash: '0'.repeat(64),\n    system: '',\n    messages: [{ role: 'user', content: [{ type: 'text', text: 'hello' }] }],\n    tools: [],\n  }\n  const config = {\n    routes: [{ route: 'demo', api: adapter.api, baseUrl: model.baseUrl, models: [model], keyless: true }],\n  }\n  const result = await runModelAdapter(adapter, {\n    config,\n    route: 'demo',\n    request: request,\n  })\n  assert.equal(result.models[0].id, 'demo-model')\n  assert.equal(result.events[0].type, 'text_delta')\n  assert.deepEqual(result.events.at(-1), { type: 'done', reason: 'stop' })\n  const cancelled = new AbortController()\n  cancelled.abort()\n  await assert.rejects(runModelAdapter(adapter, { config, route: 'demo', request, signal: cancelled.signal }))\n})\n",
    "model-adapter/tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2023\",\n    \"module\": \"NodeNext\",\n    \"moduleResolution\": \"NodeNext\",\n    \"strict\": true,\n    \"declaration\": true,\n    \"outDir\": \"dist\",\n    \"rootDir\": \"src\",\n    \"skipLibCheck\": true,\n    \"types\": [\"node\"]\n  },\n  \"include\": [\"src/**/*.ts\"]\n}\n",
